"""Validation service for DQR1HL (DQRP2), generated by the DQVP pipeline.

In the MonitoringSite entity, the location attribute must contain at least 100 percent non-empty values

The check is the DQVP constraint c-dqr1hl, compiled by the policy checker in
../heleade/policy_checker.ttl. It reads the data in place with DuckDB and returns the measured
value and whether DQR1HL is satisfied. service.json records where it comes from.

Run:  python validation_job.py [data folder]
      docker build -t dqr1hl . && docker run --rm -v <data folder>:/data dqr1hl /data
"""
import operator
import sys
from pathlib import Path

import duckdb

DATA = Path(__file__).resolve().parent / '../../tools/dqvp/data/heleade'
LOADS = {'monitoring_site': "read_csv_auto('{data}/monitoring_site.csv')"}          # table -> load expression; {data} is the data folder
MEASURE = 'select 100.0*count("location")/nullif(count(*),0) from "monitoring_site"'
COMPARE, THRESHOLD = '>=', 100.0
OPS = {">=": operator.ge, "<=": operator.le, "==": operator.eq,
       ">": operator.gt, "<": operator.lt, "!=": operator.ne}


def run_validation(data_dir=DATA):
    """(measured value, satisfied); (None, None) when nothing can be measured."""
    con = duckdb.connect()
    for table, load in LOADS.items():
        con.execute(f'CREATE TABLE "{table}" AS SELECT * FROM '
                    + load.replace("{data}", Path(data_dir).as_posix()))
    value = con.execute(MEASURE).fetchone()[0]
    if value is None:
        return None, None
    value = round(float(value), 4)
    return value, OPS[COMPARE](value, THRESHOLD)


if __name__ == "__main__":
    value, ok = run_validation(sys.argv[1] if len(sys.argv) > 1 else DATA)
    print(f"DQR1HL  {value}  {'SATISFIED' if ok else 'VIOLATED'}")
